from pathlib import Path
import shutil,json
base=Path(__file__).resolve().parent
import subprocess
durations=[float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',str(base/'narration'/f'{i}.wav')]))+.85 for i in range(6)]
scenes=[('聊过的重点，找回原文。','怎么做到？先看这份聊天记忆。','搜索「AI 硬件」','读书会 · 14:32 · 发言人 2','我们可以先做一个小样，再找真实用户试试。',5),('聊得尽兴，散场就忘？','边听边记，反而错过好话题。','想聊的话很多','当时觉得记住了','过几天：是谁说的来着？',5),('先聊天，轻点开始记录。','无需注册，即可本地录音。','① 开始本地录音','录音前，请确保现场人员知情同意','录音原件保存在你的手机。',6),('结束后，把对话变成重点。','主动发起整理，再搜索自己的历史记录。','② AI 整理 → 摘要与行动项','③ 搜索话题 → 查看原文来源','AI 需自备某云服务 Key；联网处理，费用自理。',7),('认识彼此，也留下一场回顾。','微×扫码加入，填一句「关于我」。','最近在做什么？','今天想聊什么？','回顾由组织者查看、确认后发布。',6),('倾盖如故','把每一次见面留下来。','Android App · MIT 开源','了解产品与下载','qgrg.bebackpacker.com',5)]
for name,w,h in [('social',1080,1920),('xiaohongshu',1080,1440),('website',1920,1080)]:
 d=base/name;d.mkdir(exist_ok=True);(d/'assets').mkdir(exist_ok=True);shutil.copy(base/'DESIGN.md',d/'DESIGN.md')
 shutil.copy(base.parent/'product-video/douyin/assets/logo.png',d/'assets/logo.png')
 subprocess.run(['ffmpeg','-y','-loglevel','error','-stream_loop','-1','-i',str(base.parent/'product-video/douyin/assets/music.wav'),'-t',str(sum(durations)),str(d/'assets/music.wav')],check=True)
 html=[];anim=[];t=0
 for i,(title,sub,a,b,c,dur) in enumerate(scenes):
  dur=durations[i]
  shutil.copy(base/'narration'/f'{i}.wav',d/'assets'/f'voice-{i}.wav')
  html.append(f'<audio id="vo-{i}" src="assets/voice-{i}.wav" data-start="{t+.35}" data-duration="{dur-.85}" data-track-index="2" data-volume="1"></audio>')
  if name=='website' and i==1:title='交流结束，信息仍可回溯。';sub='让现场交流与会后整理，各得其所。'
  html.append(f'<section id="s{i}" class="scene" style="z-index:{i+1};opacity:{0 if i else 1}"><div class="ring" data-layout-ignore></div><div class="scene-content" data-hold="旁白讲解与阅读停留"><div class="eyebrow">倾盖如故 · {"功能示意" if i<5 else "把每一次见面留下来"}</div><div class="layout"><div class="copy"><h1>{title}</h1><p>{sub}</p></div><div class="demo"><div class="tag">{a}</div><div class="line">{b}</div><div class="quote">{c}</div>{"<div class=wave>▂ ▅ ▃ ▇ ▄ ▆ ▂ ▅ ▃ ▇ ▄ ▆ ▂</div>" if i==2 else ""}<div class="stamp">{"内容为示意，非真实参与者资料" if i<5 else "<img src=assets/logo.png>"}</div></div></div><div class="caption">{sub}</div><div class="counter">0{i+1} / 06</div></div></section>')
  if i:anim.append(f'tl.to("#s{i}",{{opacity:1,duration:.55,ease:"sine.inOut"}},{t});tl.set("#s{i-1}",{{opacity:0}},{t+.55});')
  for j,sel in enumerate(['.eyebrow','h1','p','.tag','.line','.quote','.stamp','.caption','.counter']):
   anim.append(f'tl.from("#s{i} {sel}",{{y:{24 if j%2 else 35},opacity:{.25 if i==0 else 0},duration:.45,ease:"{["power3.out","sine.out","expo.out"][j%3]}"}},{t+.12+j*.065});')
  anim.append(f'tl.from("#s{i} .demo",{{scale:.97,duration:.65,ease:"power2.out"}},{t+.2});tl.to("#s{i} .ring",{{rotation:16,scale:1.08,duration:{dur},ease:"sine.inOut"}},{t});tl.set("#s{i-1}",{{opacity:0}},{t+.55});')
  t+=dur
 css=f'''*{{box-sizing:border-box}}html,body{{margin:0;width:{w}px;height:{h}px;overflow:hidden;background:#F7F4EE;color:#282F28;font-family:"PingFang SC",sans-serif}}#root{{width:100%;height:100%;position:relative}}.scene{{position:absolute;inset:0;overflow:hidden;background:#F7F4EE}}.scene-content{{width:100%;height:100%;padding:100px 110px;display:flex;flex-direction:column;gap:36px}}.eyebrow{{font-size:28px;color:#426B4E;letter-spacing:4px}}.layout{{flex:1;min-height:0;display:flex;gap:90px;align-items:center}}.copy{{flex:1}}h1{{font:900 94px/1.25 "Songti SC",serif;letter-spacing:-3px;max-width:850px;margin:0 0 32px}}p{{font-size:36px;line-height:1.6;color:#426B4E;margin:0;max-width:800px}}.demo{{width:660px;background:#E8EDE1;padding:46px;border-radius:38px;display:flex;flex-direction:column;gap:32px;box-shadow:0 24px 70px #426B4E14}}.tag{{font-size:34px;background:#426B4E;color:#F7F4EE;border-radius:22px;padding:24px;line-height:1.5}}.line{{font-size:30px;line-height:1.6;color:#426B4E}}.quote{{font:600 40px/1.6 "Songti SC",serif;background:#F7F4EE;padding:30px;border-radius:24px}}.stamp{{font-size:28px;color:#426B4E}}.stamp img{{width:120px;height:120px;object-fit:contain}}.caption{{font-size:30px;line-height:1.5;text-align:center;border-top:1px solid #426B4E40;padding-top:26px}}.counter{{font-size:28px;color:#426B4E}}.ring{{position:absolute;width:600px;height:600px;border:1px solid #426B4E22;border-radius:50%;right:-200px;top:-300px}}.wave{{font-size:40px;color:#426B4E;letter-spacing:4px}}'''
 if w<h:css+='''.scene-content{padding:110px 90px 200px;gap:40px}.layout{flex-direction:column;align-items:stretch;justify-content:center;gap:64px}.copy{flex:0}h1{font-size:98px;max-width:880px}.demo{width:100%;padding:40px;gap:28px}.quote{font-size:40px}.caption{font-size:32px}.counter{font-size:28px}.eyebrow{font-size:28px}'''
 if h==1440:css+='''.scene-content{padding:80px 85px 150px;gap:24px}.layout{gap:34px}h1{font-size:82px;margin-bottom:22px}.demo{gap:20px;padding:30px}.tag{padding:18px}.quote{padding:22px;font-size:34px}.caption{font-size:28px}'''
 doc=f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width={w}, height={h}"><script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script><style>@font-face{{font-family:"PingFang SC";src:local("PingFangSC-Regular")}}@font-face{{font-family:"Songti SC";src:local("STSongti-SC-Regular")}}{css}</style><body><div id="root" data-composition-id="main" data-start="0" data-duration="{t}" data-width="{w}" data-height="{h}">'+''.join(html)+f'<audio id="music" src="assets/music.wav" data-start="0" data-duration="{t}" data-track-index="1" data-volume="0.45"></audio></div><script>window.__timelines={{}};const tl=gsap.timeline({{paused:true}});'+''.join(anim)+'window.__timelines.main=tl;</script></body></html>'
 (d/'index.html').write_text(doc);(d/'hyperframes.json').write_text(json.dumps({'$schema':'https://hyperframes.heygen.com/schema/hyperframes.json'}))
 (d/'package.json').write_text(json.dumps({'private':True,'scripts':{'check':'npx -y hyperframes@0.8.221 check','render':'npx -y hyperframes@0.8.221 render --workers 1 --output review.mp4'}}))
print('三个画幅工程与样音 A 正式旁白已生成')
